CREATE TABLE IF NOT EXISTS payments(order_id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,amount INT NOT NULL CHECK(amount>0),status VARCHAR(16) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS outbox(event_key VARCHAR(100) PRIMARY KEY,order_id VARCHAR(64) NOT NULL,kind VARCHAR(20) NOT NULL,delivered INT DEFAULT 0 NOT NULL,attempts INT DEFAULT 0 NOT NULL,next_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);